{
  "implementation": "import math

def solve(case):
    matrix = case.get('matrix')
    if not matrix or not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError("Matrix is empty or invalid")
    n_rows = len(matrix)
    if not all(isinstance(row, list) for row in matrix):
        raise ValueError("Rows must be lists")
    col_len = len(matrix[0])
    if col_len == 0:
        raise ValueError("Matrix has no columns")
    for row in matrix:
        if len(row) != col_len:
            raise ValueError("Matrix not rectangular")
    df = [0] * col_len
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    idf_vals = []
    for d in df:
        idf_vals.append(math.log(1 + n_rows / (1 + d)))
    idf = [round(v, 6) for v in idf_vals]
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = []
        row_sum = 0.0
        for j, val in enumerate(row):
            w = val * idf_vals[j]
            weighted_row.append(round(w, 6))
            row_sum += w
        weighted_matrix.append(weighted_row)
        row_degree.append(round(row_sum, 6))
    return {
        "idf": idf,
        "row_degree": row_degree,
        "weighted_matrix": weighted_matrix
    }"
}
